-- The firm's email introduction (2026-10-26): company intro, services, office
-- timing, mission, founder (name, designation, photo, introduction) and the
-- firm's own fields, edited at Settings → Email introduction and filled into
-- client emails as {{firm.*}} (src/lib/firm/email-intro.ts).
ALTER TABLE tenants ADD COLUMN IF NOT EXISTS email_intro jsonb NOT NULL DEFAULT '{}'::jsonb;

-- The new-lead welcome emails (template keys lead_welcome, lead_welcome_referral,
-- sent by the "Welcome email to a new lead" automation) now introduce the firm.
-- A firm that already has them gets the new design as a new approved version,
-- made current — but ONLY where the current version is still exactly the
-- vendor starter. A copy the firm edited is left as it is. Versions are
-- immutable, so the old one stays in the template's history. Idempotent: once
-- upgraded, the current version no longer matches the old starter.
WITH upd(key, old_body, new_body) AS (
  VALUES
  ('lead_welcome', $j${"subject":"Thank you for connecting with {{tenant_display_name}}","blocks":[{"type":"header","title":"Thank you for connecting 🙏"},{"type":"text","content":"Hi {{name}},\n\nThank you for connecting with {{tenant_display_name}}. We're glad to have the chance to help you with your investments.\n\nOne of our advisors will reach out to you shortly to understand your goals. If you have any questions in the meantime, just reply to this email.\n\nWarm regards,\n{{tenant_display_name}}"}],"textFallback":"Hi {{name}}, thank you for connecting with {{tenant_display_name}}. One of our advisors will reach out to you shortly."}$j$::jsonb, $j${"mode":"designer","subject":"Thank you for connecting with {{tenant.displayName}}","preheader":"A little about who we are, and what happens next.","blocks":[{"id":"lw1","type":"logo"},{"id":"lw2","type":"hero","title":"Welcome, {{name}}","subtitle":"Thank you for reaching out to us.","imageUrl":"","imageAlt":"","align":"center"},{"id":"lw3","type":"text","align":"left","html":"Dear {{name}},<br><br>Thank you for connecting with <b>{{tenant.displayName}}</b>. We're glad to have the chance to help you with your investments.<br><br>One of our advisors will reach out to you shortly to understand your goals. If you have any questions in the meantime, just reply to this email."},{"id":"lw4h","type":"heading","text":"About {{tenant.displayName}}","level":"h3","align":"left","showIf":"firm.company_intro"},{"id":"lw4t","type":"text","html":"{{firm.company_intro}}","align":"left","showIf":"firm.company_intro"},{"id":"lw5h","type":"heading","text":"Our services","level":"h3","align":"left","showIf":"firm.services"},{"id":"lw5t","type":"text","html":"{{firm.services}}","align":"left","showIf":"firm.services"},{"id":"lw6h","type":"heading","text":"Our mission","level":"h3","align":"left","showIf":"firm.mission"},{"id":"lw6t","type":"text","html":"{{firm.mission}}","align":"left","showIf":"firm.mission"},{"id":"lw7h","type":"heading","text":"Meet our founder","level":"h3","align":"left","showIf":"firm.founder_name"},{"id":"lw7p","type":"image","url":"{{firm.founder_photo_url}}","alt":"Our founder","width":120,"align":"left","showIf":"firm.founder_photo_url"},{"id":"lw7n","type":"text","html":"<b>{{firm.founder_name}}</b><br>{{firm.founder_designation}}","align":"left","showIf":"firm.founder_name"},{"id":"lw7t","type":"text","html":"{{firm.founder_intro}}","align":"left","showIf":"firm.founder_intro"},{"id":"lw8","type":"text","html":"<b>Office timing:</b> {{firm.office_timing}}","align":"left","showIf":"firm.office_timing"},{"id":"lw9","type":"text","html":"Warm regards,<br>Team {{tenant.displayName}}","align":"left"}],"footer":{"includeArn":true,"includeAddress":true,"includeUnsubscribe":true}}$j$::jsonb),
  ('lead_welcome_referral', $j${"subject":"Thank you for connecting with {{tenant_display_name}}","blocks":[{"type":"header","title":"Thank you for connecting 🙏"},{"type":"text","content":"Hi {{name}},\n\nThank you for connecting with {{tenant_display_name}} — and a special thank-you to {{referred_by_name}}, who referred you to us. We're grateful for the introduction.\n\nOne of our advisors will reach out shortly to understand your goals. Feel free to reply to this email anytime.\n\nWarm regards,\n{{tenant_display_name}}"}],"textFallback":"Hi {{name}}, thank you for connecting with {{tenant_display_name}} — and thanks to {{referred_by_name}} for referring you. An advisor will reach out shortly."}$j$::jsonb, $j${"mode":"designer","subject":"Thank you for connecting with {{tenant.displayName}}","preheader":"A little about who we are, and what happens next.","blocks":[{"id":"lw1","type":"logo"},{"id":"lw2","type":"hero","title":"Welcome, {{name}}","subtitle":"Thank you for reaching out to us.","imageUrl":"","imageAlt":"","align":"center"},{"id":"lw3","type":"text","align":"left","html":"Dear {{name}},<br><br>Thank you for connecting with <b>{{tenant.displayName}}</b> — and a special thank-you to {{referred_by_name}}, who introduced you to us. We're grateful for the introduction.<br><br>One of our advisors will reach out to you shortly to understand your goals. If you have any questions in the meantime, just reply to this email."},{"id":"lw4h","type":"heading","text":"About {{tenant.displayName}}","level":"h3","align":"left","showIf":"firm.company_intro"},{"id":"lw4t","type":"text","html":"{{firm.company_intro}}","align":"left","showIf":"firm.company_intro"},{"id":"lw5h","type":"heading","text":"Our services","level":"h3","align":"left","showIf":"firm.services"},{"id":"lw5t","type":"text","html":"{{firm.services}}","align":"left","showIf":"firm.services"},{"id":"lw6h","type":"heading","text":"Our mission","level":"h3","align":"left","showIf":"firm.mission"},{"id":"lw6t","type":"text","html":"{{firm.mission}}","align":"left","showIf":"firm.mission"},{"id":"lw7h","type":"heading","text":"Meet our founder","level":"h3","align":"left","showIf":"firm.founder_name"},{"id":"lw7p","type":"image","url":"{{firm.founder_photo_url}}","alt":"Our founder","width":120,"align":"left","showIf":"firm.founder_photo_url"},{"id":"lw7n","type":"text","html":"<b>{{firm.founder_name}}</b><br>{{firm.founder_designation}}","align":"left","showIf":"firm.founder_name"},{"id":"lw7t","type":"text","html":"{{firm.founder_intro}}","align":"left","showIf":"firm.founder_intro"},{"id":"lw8","type":"text","html":"<b>Office timing:</b> {{firm.office_timing}}","align":"left","showIf":"firm.office_timing"},{"id":"lw9","type":"text","html":"Warm regards,<br>Team {{tenant.displayName}}","align":"left"}],"footer":{"includeArn":true,"includeAddress":true,"includeUnsubscribe":true}}$j$::jsonb)
), cur AS (
  SELECT t.id AS template_id, t.tenant_id, v.variables, v.attachments, u.new_body
    FROM templates t
    JOIN template_versions v ON v.id = t.current_version_id
    JOIN upd u ON u.key = t.key
   WHERE t.channel = 'email'
     AND v.body = u.old_body
), ins AS (
  INSERT INTO template_versions (id, template_id, tenant_id, version_number, body, variables, attachments, approval_status, approved_at)
  SELECT gen_random_uuid(), c.template_id, c.tenant_id,
         (SELECT COALESCE(max(x.version_number), 0) + 1 FROM template_versions x WHERE x.template_id = c.template_id),
         c.new_body, c.variables, c.attachments, 'approved_internal', now()
    FROM cur c
  RETURNING id, template_id
)
UPDATE templates t SET current_version_id = ins.id, updated_at = now()
  FROM ins WHERE t.id = ins.template_id;
